    let exportClipChannel = FlutterBasicMessageChannel(name: "dev.flutter.pigeon.earmark.RecorderHostApi.exportClip\(channelSuffix)", binaryMessenger: binaryMessenger, codec: codec)
    if let api = api {
      exportClipChannel.setMessageHandler { message, reply in
        let args = message as! [Any?]
        let folderArg = args[0] as! String
        let startMsArg = args[1] as! Int64
        let endMsArg = args[2] as! Int64
        let fileNameArg = args[3] as! String
        Task { @MainActor in
          do {
            let result = try await api.exportClip(folder: folderArg, startMs: startMsArg, endMs: endMsArg, fileName: fileNameArg)
            reply(wrapResult(result))
          } catch {
            reply(wrapError(error))
          }
        }
      }
    } else {
      exportClipChannel.setMessageHandler(nil)
    }
    /// Debug builds only: duration and test-tone pitch of an audio file.
    let probeAudioChannel = FlutterBasicMessageChannel(name: "dev.flutter.pigeon.earmark.RecorderHostApi.probeAudio\(channelSuffix)", binaryMessenger: binaryMessenger, codec: codec)
    if let api = api {
      probeAudioChannel.setMessageHandler { message, reply in
        let args = message as! [Any?]
        let pathArg = args[0] as! String
        Task { @MainActor in
          do {
            let result = try await api.probeAudio(path: pathArg)
            reply(wrapResult(result))
          } catch {
            reply(wrapError(error))
          }
        }
      }
    } else {
      probeAudioChannel.setMessageHandler(nil)
    }
    /// Debug builds only (ignored in release): record a clock-paced test tone instead of
    /// the microphone, for integration tests on emulators whose mic clock is unreliable.
    /// Also keeps the screen on while the test runs.
    let useTestToneChannel = FlutterBasicMessageChannel(name: "dev.flutter.pigeon.earmark.RecorderHostApi.useTestTone\(channelSuffix)", binaryMessenger: binaryMessenger, codec: codec)
    if let api = api {
      useTestToneChannel.setMessageHandler { message, reply in
        let args = message as! [Any?]
        let onArg = args[0] as! Bool
        do {
          try api.useTestTone(on: onArg)
          reply(wrapResult(nil))
        } catch {
          reply(wrapError(error))
        }
      }
    } else {
      useTestToneChannel.setMessageHandler(nil)
    }
  }
}

